<?php require __DIR__.'/../app/bootstrap.php';require_login();$u=current_user($pdo);if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$network=strtolower(trim($_POST['network']??''));$phone=preg_replace('/\D+/','',$_POST['phone']??'');$amount=(float)($_POST['amount']??0);if(!in_array($network,['mtn','airtel','glo','9mobile'],true)||!phone_ok($phone)||$amount<50){flash('error','Enter a valid network, Nigerian phone number and amount.');header('Location:/buy-airtime.php');exit;}try{$pdo->beginTransaction();$q=$pdo->prepare('SELECT balance FROM wallets WHERE user_id=? FOR UPDATE');$q->execute([$u['id']]);$bal=(float)$q->fetchColumn();$charge=round($amount*1.01,2);if($bal<$charge)throw new RuntimeException('Insufficient wallet balance.');$ref='AIR-'.date('YmdHis').'-'.bin2hex(random_bytes(4));$pdo->prepare('UPDATE wallets SET balance=balance-? WHERE user_id=?')->execute([$charge,$u['id']]);$pdo->prepare('INSERT INTO wallet_transactions(user_id,type,amount,reference,description) VALUES(?,?,?,?,?)')->execute([$u['id'],'debit',$charge,$ref,'Airtime purchase']);$wt=(int)$pdo->lastInsertId();$pdo->prepare('INSERT INTO service_transactions(user_id,service,customer,network,amount,cost_amount,reference) VALUES(?,?,?,?,?,?,?)')->execute([$u['id'],'airtime',$phone,$network,$charge,$amount,$ref]);$sid=(int)$pdo->lastInsertId();$pdo->commit();try{$r=(new VtuProvider($config['vtu']))->purchaseAirtime($network,$phone,$amount,$ref);if(!provider_ok($r))throw new RuntimeException($r['message']??'Airtime order failed.');$pdo->prepare('UPDATE service_transactions SET status="successful",provider_reference=? WHERE id=?')->execute([provider_ref($r),$sid]);notify($pdo,$u['id'],'Airtime successful','Airtime of '.money($amount).' was sent to '.$phone.'.');flash('success','Airtime purchase successful.');}catch(Throwable $ex){$pdo->beginTransaction();$pdo->prepare('UPDATE service_transactions SET status="reversed" WHERE id=?')->execute([$sid]);$pdo->prepare('UPDATE wallet_transactions SET status="reversed" WHERE id=?')->execute([$wt]);$pdo->prepare('UPDATE wallets SET balance=balance+? WHERE user_id=?')->execute([$charge,$u['id']]);$pdo->commit();flash('error','Airtime purchase failed; your wallet was reversed.');}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('error',$e->getMessage());}header('Location:/buy-airtime.php');exit;}require __DIR__.'/../app/layout.php';header_html('Airtime');?><div class="card narrow"><h2>Buy Airtime</h2><p class="muted">A 1% service markup is included in the wallet charge.</p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="field"><label>Network</label><select name="network" required><option value="">Select network</option><option>MTN</option><option>Airtel</option><option>Glo</option><option>9mobile</option></select></div><div class="field"><label>Phone number</label><input name="phone" inputmode="numeric" required></div><div class="field"><label>Airtime amount</label><input name="amount" type="number" min="50" step="1" required></div><button class="btn">Buy Airtime</button></form></div><?php footer_html();
